import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * A customer's dealings with the MHPCO, worked through in order.
 *
 * <p>Holds the MHPCO's reading of how one step bears on the next: the steps of
 * a scenario are settled sequentially for a single customer, every contract
 * concluded before a step makes that step a follow-up contract, and a claim is
 * settled against the policy an earlier quote wrote. Knows nothing about the
 * wire format a scenario arrived in or its results are written back in.
 */
final class Scenario {

    private final Customer customer;
    private final List<Step> steps;

    Scenario(Customer customer, List<Step> steps) {
        this.customer = customer;
        this.steps = List.copyOf(steps);
    }

    /**
     * The result of every step, in the order the MHPCO worked through them.
     */
    List<StepResult> settle() {
        List<StepResult> results = new ArrayList<>();
        Map<Integer, Policy> policies = new HashMap<>();
        int contracts = 0;
        for (int index = 0; index < steps.size(); index++) {
            Step step = steps.get(index);
            if (step instanceof QuoteStep quote) {
                policies.put(index, new Policy(quote.items()));
                results.add(new QuoteResult(
                        PremiumCalculator.premiumFor(customer, contracts, quote.items())));
                contracts++;
            } else if (step instanceof ClaimStep claim) {
                Policy policy = policies.get(claim.policy());
                results.add(new ClaimResult(
                        WholeG.payout(policy.settle(claim.incident())),
                        WholeG.payout(policy.remainingCap())));
            }
        }
        return results;
    }
}
