import java.math.BigDecimal;
import java.util.List;

/**
 * A policy the MHPCO has written over a list of items.
 *
 * <p>Knows the insurance sum it covers and how much of its payout cap is still
 * available: the MHPCO pays out at most twice the insurance sum over the life
 * of a policy, whatever the premium modifiers were.
 */
final class Policy {

    private static final BigDecimal CAP_MULTIPLE = BigDecimal.valueOf(2);

    private final List<Item> items;
    private BigDecimal remainingCap;

    Policy(List<Item> items) {
        this.items = List.copyOf(items);
        this.remainingCap = InsuranceSum.of(this.items).multiply(CAP_MULTIPLE);
    }

    List<Item> items() {
        return items;
    }

    BigDecimal remainingCap() {
        return remainingCap;
    }

    /**
     * Settles an incident against this policy, reducing the remaining cap by
     * what is paid out.
     */
    BigDecimal settle(Incident incident) {
        BigDecimal payout = Reimbursement.of(incident).min(remainingCap);
        remainingCap = remainingCap.subtract(payout);
        return payout;
    }
}
