import java.math.BigDecimal;

/**
 * What the MHPCO reimburses for an incident, before the policy's cap is
 * applied.
 *
 * <p>Knows that a deductible applies per damage event — once for each damaged
 * item — and defers to the damage clauses how much of a single damage the
 * MHPCO reimburses at all.
 */
final class Reimbursement {

    private static final BigDecimal DEDUCTIBLE_IN_G = BigDecimal.valueOf(100);

    private Reimbursement() {
    }

    static BigDecimal of(Incident incident) {
        return incident.damages().stream()
                .map(Reimbursement::reimbursementFor)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    private static BigDecimal reimbursementFor(Damage damage) {
        return BigDecimal.valueOf(damage.amount()).subtract(DEDUCTIBLE_IN_G).max(BigDecimal.ZERO);
    }
}
