import java.math.BigDecimal;
import java.util.Map;
import java.util.Set;

/**
 * The MHPCO price list: the base premium each kind of item is tariffed at.
 *
 * <p>The MHPCO tariffs main items individually and components as a category:
 * every component carries the same base premium, whatever it is made of.
 *
 * <p>Changes whenever the MHPCO revises its tariff or takes on a new kind of
 * item; knows nothing about how a premium is assembled from those amounts.
 */
final class PriceList {

    private static final int SWORD_BASE_PREMIUM_IN_G = 100;
    private static final int AMULET_BASE_PREMIUM_IN_G = 60;
    private static final int STAFF_BASE_PREMIUM_IN_G = 80;
    private static final int POTION_BASE_PREMIUM_IN_G = 40;

    private static final int COMPONENT_BASE_PREMIUM_IN_G = 25;

    private static final int NOT_TARIFFED = 0;

    private static final int SWORD_INSURANCE_VALUE_IN_G = 1000;
    private static final int AMULET_INSURANCE_VALUE_IN_G = 600;
    private static final int STAFF_INSURANCE_VALUE_IN_G = 800;
    private static final int POTION_INSURANCE_VALUE_IN_G = 400;
    private static final int COMPONENT_INSURANCE_VALUE_IN_G = 250;

    private static final Map<String, Integer> MAIN_ITEM_INSURANCE_VALUES_IN_G = Map.of(
            "sword", SWORD_INSURANCE_VALUE_IN_G,
            "amulet", AMULET_INSURANCE_VALUE_IN_G,
            "staff", STAFF_INSURANCE_VALUE_IN_G,
            "potion", POTION_INSURANCE_VALUE_IN_G);

    private static final Map<String, Integer> MAIN_ITEM_BASE_PREMIUMS_IN_G = Map.of(
            "sword", SWORD_BASE_PREMIUM_IN_G,
            "amulet", AMULET_BASE_PREMIUM_IN_G,
            "staff", STAFF_BASE_PREMIUM_IN_G,
            "potion", POTION_BASE_PREMIUM_IN_G);

    private static final Set<String> COMPONENT_TYPES = Set.of("rune", "moonstone");

    private PriceList() {
    }

    static BigDecimal basePremiumFor(Item item) {
        if (isComponent(item)) {
            return BigDecimal.valueOf(COMPONENT_BASE_PREMIUM_IN_G);
        }
        return BigDecimal.valueOf(MAIN_ITEM_BASE_PREMIUMS_IN_G.getOrDefault(item.type(), NOT_TARIFFED));
    }

    static BigDecimal insuranceValueFor(Item item) {
        if (isComponent(item)) {
            return BigDecimal.valueOf(COMPONENT_INSURANCE_VALUE_IN_G);
        }
        return BigDecimal.valueOf(
                MAIN_ITEM_INSURANCE_VALUES_IN_G.getOrDefault(item.type(), NOT_TARIFFED));
    }

    private static boolean isComponent(Item item) {
        return COMPONENT_TYPES.contains(item.type());
    }
}
=== WholeG.java ===
import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * The MHPCO's settlement rule: a calculation is kept as fractions throughout
 * and only its final amount is settled to whole G, always in the MHPCO's own
 * favour.
 *
 * <p>Favour has a direction, and the direction depends on which way the money
 * moves. On a premium, money the MHPCO receives, favour rounds up. On a
 * payout, money the MHPCO pays out, favour rounds down. The two are stated
 * together here so the asymmetry is visible rather than rediscovered.
 *
 * <p>Changes whenever the MHPCO revises how it settles fractions; knows
 * nothing about how any amount was arrived at.
 */
final class WholeG {

    private WholeG() {
    }

    /**
     * Settles a premium — money the MHPCO receives — so a fraction of a G
     * falls to the MHPCO.
     */
    static int premium(BigDecimal amount) {
        return amount.setScale(0, RoundingMode.CEILING).intValueExact();
    }

    /**
     * Settles a payout — money the MHPCO pays out — so a fraction of a G stays
     * with the MHPCO.
     */
    static int payout(BigDecimal amount) {
        return amount.setScale(0, RoundingMode.FLOOR).intValueExact();
    }
}
